0	8	x1 = 0      % index
1	9	x2 = [0]    % N
2	10	x3 = 4      % input address
3	11	x4 = 16     % output address
4	12	x8 = 0      % previous sample x[n-1]
5	13	x9 = 0      % previous-previous sample x[n-2]
6	16	x5 = x1 - x2
7	17	BEQ .exit
8	19	x6 = [x3]   % current sample
9	20	x7 = x6 * 1
10	21	x10 = x8 * 2
11	22	x11 = x9 * 1
12	23	x12 = x7 + x10
13	24	x12 = x12 + x11
14	25	[x4] = x12
15	27	x9 = x8 + 0
16	28	x8 = x6 + 0
17	29	x3 = x3 + 4
18	30	x4 = x4 + 4
19	31	x1 = x1 + 1
20	32	BAL .loop
